repo.trades.py:
"""Trade records."""


class Trade:
    def __init__(self, desk, volume):
        self.desk = desk
        self.volume = volume

    def __repr__(self):
        return "Trade(%r, %r)" % (self.desk, self.volume)


ROWS = [('metals', 59), ('fx', 53), ('energy', 19), ('bonds', 23), ('fx', 17), ('fx', 47)]


def load_trades():
    """Yield the stored trades one at a time."""
    for desk, volume in ROWS:
        yield Trade(desk, volume)

