"""Top trades by volume."""


def _take_largest(trades):
    """Remove and return the trade with the largest volume."""
    best = max(trades, key=lambda x: x.volume)
    trades.remove(best)
    return best


def podium(trades, places=3):
    """Return the top `places` trades by volume, largest first. The caller's list is left as it was."""
    top = []
    while trades and len(top) < places:
        top.append(_take_largest(trades))
    return top


def report(trades):
    """Return the podium values, the number of trades and every volume."""
    return {"podium": [x.volume for x in podium(trades)], "count": len(trades), "all": [x.volume for x in trades]}


def largest_volume(trades):
    """Return the largest volume, or None when there are no trades."""
    values = [x.volume for x in trades]
    return max(values) if values else None

