from trades import load_trades, ROWS
from podium import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_trades()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_trades()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_trades()))
    assert [x.volume for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_trades())
    podium(data, 2)
    assert [x.volume for x in data] == VALUES


def test_one_place():
    assert [x.volume for x in podium(list(load_trades()), 1)] == [max(VALUES)]
